package com.example.madfinalproject.coach;
import com.example.madfinalproject.models.VisaInterviewQuestion; import com.example.madfinalproject.repository.VisaInterviewRepository; import com.example.madfinalproject.utils.LogUtils; import com.google.android.gms.tasks.Task; import com.google.firebase.auth.FirebaseAuth; import com.google.firebase.firestore.FieldValue; import com.google.firebase.firestore.FirebaseFirestore; import java.text.SimpleDateFormat; import java.util.Date; import java.util.HashMap; import java.util.List; import java.util.Locale; import java.util.Map;
public final class DailyChallengeService { public Task<VisaInterviewQuestion> getToday(String country){return VisaInterviewRepository.getInstance().getQuestionsByCountry(country).continueWith(task->{if(!task.isSuccessful())throw task.getException();List<VisaInterviewQuestion>q=task.getResult();if(q.isEmpty())throw new IllegalStateException("No challenge question available");String day=new SimpleDateFormat("yyyyMMdd",Locale.US).format(new Date());return q.get(Math.abs((country+day).hashCode())%q.size());});} public void markCompleted(VisaInterviewQuestion q,int streak){String uid=FirebaseAuth.getInstance().getUid();if(uid==null)uid="guest";String day=new SimpleDateFormat("yyyyMMdd",Locale.US).format(new Date());Map<String,Object>d=new HashMap<>();d.put("userId",uid);d.put("questionId",q.getId());d.put("completed",true);d.put("streak",streak);d.put("timestamp",FieldValue.serverTimestamp());FirebaseFirestore.getInstance().collection("userDailyChallenge").document(uid+"_"+day).set(d).addOnSuccessListener(v->LogUtils.d("VisaCoach","Challenge completed"));} }
